package fable.hideseek.imba.client;
import fable.hideseek.imba.config.MaskHitboxConfig;import fable.hideseek.imba.net.MaskHitboxNetworking;import net.fabricmc.fabric.api.client.networking.v1.ClientPlayNetworking;import java.util.LinkedHashMap;
public final class MaskHitboxClientNetworking{private MaskHitboxClientNetworking(){}public static void register(){ClientPlayNetworking.registerGlobalReceiver(MaskHitboxNetworking.SYNC,(client,handler,buf,sender)->{int count=Math.max(0,Math.min(100000,buf.readVarInt()));var next=new LinkedHashMap<String,MaskHitboxClientData.Entry>();for(int i=0;i<count;i++){String id=buf.readString(256);boolean custom=buf.readBoolean();var b=new MaskHitboxConfig.Bounds(buf.readFloat(),buf.readFloat(),buf.readFloat(),buf.readFloat(),buf.readFloat(),buf.readFloat());next.put(id,new MaskHitboxClientData.Entry(custom,b));}client.execute(()->{MaskHitboxClientData.replace(next);if(client.currentScreen instanceof MaskHitboxConfigScreen screen)screen.applyServerState();});});}}
